"""Create a portable, dependency-free results page for the HW3 video."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
h=root/'training/hw3'
s=json.loads((h/'results/summary.json').read_text())
names={'baseline':'HW2 MLP','concat':'Concatenation','fixed':'Fixed fusion','gated':'Learned gate'}
rows=''.join(f"<tr><td>{names[v]}</td><td>{m['accuracy']['mean']*100:.2f}% ± {m['accuracy']['std_across_folds']*100:.2f}</td><td>{m['macro_f1']['mean']:.3f}</td><td>{m['parameters']:,}</td><td>{m['mean_training_seconds']:.1f}s</td></tr>" for v,m in s['models'].items())
html='''<!doctype html><html lang="en"><meta charset="utf-8"><title>HW3 · Temporal Gating Study</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f3f8;color:#242638;font:18px/1.5 system-ui,sans-serif}header{padding:28px 6%;background:#25223d;color:white}header small{color:#cabcf4;letter-spacing:2px}h1{font-size:34px;margin:8px 0}header p{margin:0;color:#dfdaed}nav{position:sticky;top:0;background:white;padding:12px 6%;display:flex;gap:12px;box-shadow:0 3px 12px #0001;z-index:1}button{border:0;background:#eeebf7;color:#413361;padding:12px 20px;border-radius:8px;font:inherit;cursor:pointer}button.active{background:#6652b8;color:white}main{max-width:1200px;margin:24px auto;padding:0 24px}.panel{display:none}.panel.active{display:block}.card{background:white;border-radius:14px;padding:24px;margin:18px 0}h2{margin:0 0 12px;font-size:27px}h3{margin:0 0 10px}p{margin:10px 0}img{max-width:100%;display:block;margin:auto}table{width:100%;border-collapse:collapse;font-size:17px}td,th{text-align:left;padding:13px 10px;border-bottom:1px solid #e6e3ee}th{color:#625675} .grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.tag{display:inline-block;background:#eeeafa;padding:5px 10px;border-radius:6px;font-size:15px;margin:5px}.note{color:#646070;font-size:16px}a{color:#6652b8}footer{font-size:14px;color:#716c7f;padding:15px 6%}
</style><header><small>DS7400 · HOMEWORK 3</small><h1>Does temporal information need a learned gate?</h1><p>A controlled extension of the HW2 sound classifier on UrbanSound8K.</p></header><nav>
<button class="active" data-tab="question">1 · Question</button><button data-tab="design">2 · Design</button><button data-tab="results">3 · Results</button><button data-tab="analysis">4 · Analysis</button></nav><main>
<section id="question" class="panel active"><div class="card"><h2>From 240 clips to 8,732</h2><div class="grid"><div><h3>HW2 limitation</h3><p>Whole-clip means and standard deviations discard within-recording temporal structure.</p><p>Dog barks, gunshots and other short events may benefit from local information.</p></div><div><h3>Hypothesis before training</h3><p>Combine global and four ordered segment representations. Learn when to rely on each.</p><p>Risk: more parameters, short-clip padding and gate saturation may hurt generalization.</p></div></div></div><div class="card"><h2>Controlled protocol</h2><span class="tag">10 classes</span><span class="tag">10 official test folds</span><span class="tag">4 models × 80 epochs × 10 folds</span><p>For each test fold: eight folds train, the next cyclic fold validates. Five sources span official folds: related clips are purged from training/validation to isolate sources, while every test clip remains.</p><p>Same SGD, batch size, hidden width and dropout. Select checkpoints only by validation loss.</p><p class="note">New task and class set: these percentages are not comparable with HW2's six-class accuracy. One seed per fold; no test-driven tuning.</p></div></section>
<section id="design" class="panel"><div class="card"><img src="results/architecture.png" alt="Baseline and gated architecture"></div><div class="card"><table><tr><th>Model</th><th>What it tests</th></tr><tr><td>HW2 MLP</td><td>Global 168 → 64 → 10; retrained baseline</td></tr><tr><td>Concatenation</td><td>Extra segment features without branch routing</td></tr><tr><td>Fixed fusion</td><td>Two branches, constant local weight 0.5</td></tr><tr><td>Learned gate</td><td>Same branches, input-dependent scalar weight</td></tr></table><p class="note">Fixed and gated start with identical shared weights and a = 0.5. Only 129 gate parameters differ.</p></div></section>
<section id="results" class="panel"><div class="card"><h2>All ten official test folds</h2><table><tr><th>Model</th><th>Accuracy ± fold SD</th><th>Macro F1</th><th>Parameters</th><th>Train/run</th></tr>ROWS</table><p class="note">SD describes fold variability, not a confidence interval. Each recording is tested once per model. Timing includes concurrent CPU workers.</p><img src="results/comparison.png" alt="All fold scores and mean accuracy"></div></section>
<section id="analysis" class="panel"><div class="card"><h2>Evidence and interpretation</h2><div id="findings"></div></div><div class="card"><img src="results/learning-curves.png" alt="All training curves"></div><div class="card"><img src="results/diagnostics.png" alt="Gate distribution and class recall"></div><div class="card"><h3>Limits and next experiment</h3><p>One seed per fold, correlated training splits, and different parameter counts limit the conclusions. Test-time segment reversal also changes positional feature distributions.</p><p>Gate saturation is a plausible failure mechanism, not a proven cause. Next: repeat seeds, add a capacity-matched global baseline, and test gentler gates and valid-duration segments using validation data.</p><a href="report.pdf">Read the two-page experiment report</a> · <a href="03_temporal_gating.ipynb">Executed notebook</a></div></section></main><footer>Predeclared protocol and every result are included in the repository. AI assistance is disclosed in the README.</footer><script>
document.querySelectorAll('button[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.active').forEach(e=>e.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active');window.scrollTo(0,0)});
</script></html>'''
d=s['paired_accuracy_differences'];g=s['models']['gated']['gate']
findings=f"<p>Learned gate minus HW2 MLP: <strong>{d['gated_minus_baseline']['mean']*100:+.2f} percentage points</strong>; higher accuracy in {d['gated_minus_baseline']['positive_folds']}/10 folds.</p><p>Learned gate minus fixed fusion: <strong>{d['gated_minus_fixed']['mean']*100:+.2f} points</strong>; higher in {d['gated_minus_fixed']['positive_folds']}/10 folds.</p><p>Learned gate minus concatenation: <strong>{d['gated_minus_concat']['mean']*100:+.2f} points</strong>. The simplest temporal representation is an essential control.</p><p>Mean local gate: {g['mean']:.3f}; saturated (&lt;0.05 or &gt;0.95): {100*g['saturation_fraction']:.1f}%.</p>"
html=html.replace('ROWS',rows).replace('<div id="findings"></div>','<div id="findings">'+findings+'</div>')
(h/'index.html').write_text(html)
